use serde_json::{Value,json};
pub fn defaults()->Value {json!({"DeviceRemindersEnabled":false,"DeviceSoundEnabled":true,"DeviceSound":"Connect","DeviceSoundPath":"","DeviceVolume":55.,"SwipeActivities":false,"AutoCompactMaxWidth":420.,"TodoDefaultColor":"#F3D79B","TodoRemindersEnabled":true,"TodoIslandEnabled":true,"AutoCompactWidth":false,"CompactTranslation":true,"ChineseTwoLine":false,"NotificationSoundEnabled":true,"TodoSoundEnabled":true,"NotificationSound":"Soft","TodoSound":"Bell","NotificationSoundPath":"","TodoSoundPath":"","NotificationVolume":35.,"TodoVolume":45.,"CompactWidth":260.,"FontSize":12.5,"Floating":false,"Translation":true,"Animation":true,"MotionPreferenceVersion":1,"HoverExpand":false,"ClickAnywhereExpand":true,"NotificationsEnabled":false,"PauseNotifications":false,"NotificationClickOpenApp":true,"MusicClickOpenApp":false,"NotificationWhitelistEnabled":false,"NotificationAllowedApps":["QQNT","QQ"],"WordHighlight":true,"AlwaysOnTop":true,"AutoStart":false,"OnlineSongInfo":true,"CoverBackground":true,"HideWhenPaused":true,"AllowedSources":["Netease","QQMusic","Kugou","Kuwo","Spotify","TwilightEcho"],"PlayerWhitelistVersion":1,"ExpandedTextColor":"#F4F6F8","ExpandedComponentColor":"#B1E8D1","LyricProgressColor":"#A9E6CD","SettingsTheme":"System","CenterX":0.5,"TopFraction":0.08,"Display":"","OffsetMilliseconds":0,"LocalFolders":[],"Motion":crate::motion::Options::default()})}
pub fn load(path:&std::path::Path)->Value {
    let stored=lyric_backend::io::read_settings(path);let mut s=defaults();
    if let Some(fields)=stored.as_object(){for (k,v) in fields{if k=="Motion"{if let Ok(o)=serde_json::from_value::<crate::motion::Options>(v.clone()){s[k]=serde_json::to_value(o).unwrap();}}else{s[k]=v.clone();}}}
    if let Some(fields)=s.as_object_mut(){fields.remove("FollowWindowsDnd");fields.remove("NotificationCompatibility");fields.remove("CardMaterial");}
    // Validate persisted numbers before they enter geometry or a spring denominator.
    for (k,min,max,fallback) in [("AutoCompactMaxWidth",140.,480.,420.),("CompactWidth",140.,480.,260.),("FontSize",11.,17.,12.5),("CenterX",0.,1.,0.5),("TopFraction",0.,1.,0.08)]{s[k]=json!(s[k].as_f64().filter(|v|v.is_finite()).unwrap_or(fallback).clamp(min,max));}
    for (k,min,max,fallback) in [("Gap",0.,24.,8.),("Duration",250.,1200.,360.),("CollapseDuration",150.,700.,300.),("Radius",8.,48.,30.)]{s["Motion"][k]=json!(s["Motion"][k].as_f64().unwrap_or(fallback).clamp(min,max));}
    for (k,min,max,fallback) in [("Stiffness",100.,1000.,420.),("Damping",10.,80.,30.),("Mass",0.3,2.,0.8)]{s["Motion"]["Spring"][k]=json!(s["Motion"]["Spring"][k].as_f64().unwrap_or(fallback).clamp(min,max));}s
}
pub fn validate_setting(v:Value)->Result<Value,String>{
    let key=v["key"].as_str().ok_or("missing key")?;let value=&v["value"];let mut settings=v["settings"].clone();if !settings.is_object(){return Err("invalid settings".into())}
    let range=match key{"DeviceVolume"|"NotificationVolume"|"TodoVolume"=>Some((0.,100.)),"AutoCompactMaxWidth"|"CompactWidth"=>Some((140.,480.)),"FontSize"=>Some((11.,17.)),"OffsetMilliseconds"=>Some((-5000.,5000.)),"MotionGap"=>Some((0.,24.)),"MotionDuration"=>Some((250.,1200.)),"MotionCollapseDuration"=>Some((150.,700.)),"MotionRadius"=>Some((8.,48.)),"SpringStiffness"=>Some((100.,1000.)),"SpringDamping"=>Some((10.,80.)),"SpringMass"=>Some((0.3,2.)),_=>None};
    let value=if let Some((min,max))=range{let n=value.as_f64().ok_or("invalid number")?;if !n.is_finite()||n<min||n>max{return Err("number outside range".into())}if key=="OffsetMilliseconds"{json!(n.round() as i32)}else{json!(n)}}else if ["DeviceRemindersEnabled","DeviceSoundEnabled","SwipeActivities","TodoRemindersEnabled","TodoIslandEnabled","AutoCompactWidth","CompactTranslation","ChineseTwoLine","NotificationSoundEnabled","TodoSoundEnabled","Floating","Translation","Animation","HoverExpand","ClickAnywhereExpand","WordHighlight","AlwaysOnTop","AutoStart","OnlineSongInfo","HideWhenPaused","NotificationsEnabled","PauseNotifications","NotificationClickOpenApp","MusicClickOpenApp","NotificationWhitelistEnabled","CoverBackground"].contains(&key){json!(value.as_bool().ok_or("invalid bool")?)}
    else if key=="DeviceSound"||key=="NotificationSound"||key=="TodoSound"{let name=value.as_str().ok_or("invalid sound")?;if !["Soft","Glass","Bell","Connect"].contains(&name){return Err("invalid sound".into())}json!(name)}
    else if key=="DeviceSoundPath"||key=="NotificationSoundPath"||key=="TodoSoundPath"{let path=value.as_str().ok_or("invalid path")?;crate::sound::validate_file(path)?;json!(path)}
    // The settings window's own appearance. The capsule is dark by design, so this never reaches
    // the renderer — it is persisted here purely so the choice survives a restart.
    else if key=="SettingsTheme"{let s=value.as_str().ok_or("invalid theme")?;if !["System","Light","Dark"].contains(&s){return Err("invalid theme".into())}value.clone()}
    else if key.ends_with("Color"){let s=value.as_str().ok_or("invalid color")?;if !["TodoDefaultColor","ExpandedTextColor","ExpandedComponentColor","LyricProgressColor"].contains(&key)||!s.starts_with('#')||s.len()!=7||!s[1..].bytes().all(|b|b.is_ascii_hexdigit()){return Err("invalid color".into())}json!(s.to_uppercase())}
    else if key=="AllowedSources"||key=="NotificationAllowedApps"{let a=value.as_array().ok_or("invalid whitelist")?;if a.len()>32{return Err("whitelist too long".into())}let mut out=vec![];for s in a{let s=s.as_str().ok_or("invalid source")?.trim();if s.is_empty()||s.encode_utf16().count()>256{return Err("invalid source".into())}if !out.iter().any(|v:&String|v.eq_ignore_ascii_case(s)){out.push(s.to_string())}}json!(out)}else{return Err("unknown setting".into())};
    if let Some(name)=key.strip_prefix("Motion"){settings["Motion"][name]=value;}else if let Some(name)=key.strip_prefix("Spring"){settings["Motion"]["Spring"][name]=value;}else{settings[key]=value;}Ok(settings)
}


